CustomField.formula:
/* Frequency of Visits — 30% */ CASE(TEXT(Frequency_of_InStore_Visits__c), "Monthly", 0.30, "Every Other Month", 0.225, "Quarterly", 0.15, "Never (Virtual)",0.075, 0 )
/* Interaction Rate — keep existing logic */ + CASE(TEXT(Interaction_Rate__c), "Individual for this Account Only", 0.40, "Group Reporting 3-4 Stores", 0.10, "Group Reporting 5-9 Stores", 0.05, "Group Reporting 10+ Stores", 0.02, 0 )
/* Monthly Reports — now 30% */ + CASE(TEXT(Monthly_Reports__c), "4+ per month", 0.30, "4x per month", 0.21, "3x per month", 0.15, "2x per month", 0.09, 0 )
/* Primary Website — unchanged */ + IF(Does_Account_have_Primary_Website__c, 0.10, 0)
/* New categories */ + Custom_Creative_Weighted__c + Mail_Weighted__c + Case_Score__c
